        'sdk-shape',
        '--recover',
        '--project-root',
        root,
        '--json',
      ]);
      expect(recovered.exitCode).toBe(0);
      expect(JSON.parse(recovered.stdout!).data.alreadyArchived).toBe(true);
    },
  );
});

describe('Native SDK Workflow Application', () => {
