      status: 'active',
      builder_handoff: { candidate_id: candidateId },
      loop: { execution_failure_count: 0 },
    });
    expect(run.actions.at(-1)).toMatchObject({ stepId: 'verify.verifier', status: 'pending' });
    run = await succeedLatestAction(
      runtime,
      run,
      {
        candidateId,
