        );
        const migration = await nativeDoctorCommand([run.runId, '--migrate-history'], root);
        expect(migration.exitCode, JSON.stringify(migration)).toBe(0);
        expect(await fileStore.readDisposition(run.runId)).toBe('closed');
      }
    },
  );

